CREATE TABLE IF NOT EXISTS public.krim_vehicle_document_requirements (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 registration_country_code text NOT NULL CHECK(registration_country_code ~ '^[A-Z]{2}$'),
 vehicle_category text NOT NULL CHECK(length(btrim(vehicle_category)) BETWEEN 2 AND 60),
 document_type text NOT NULL CHECK(length(btrim(document_type)) BETWEEN 2 AND 80),
 is_required boolean NOT NULL DEFAULT true,
 created_by uuid NOT NULL REFERENCES auth.users(id),
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS krim_vehicle_doc_req_unique_idx ON public.krim_vehicle_document_requirements(registration_country_code,lower(vehicle_category),document_type);
ALTER TABLE public.krim_vehicle_document_requirements ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.krim_vehicle_document_requirements FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_admin_guard()
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=auth.uid();
BEGIN
 IF v_user IS NULL OR coalesce(auth.jwt()->>'aal','')<>'aal2' THEN RAISE EXCEPTION USING errcode='42501',message='Platform verification requires an authenticated MFA (AAL2) session';END IF;
 IF NOT private.krim_has_permission(v_user,1,'admin.platform') THEN RAISE EXCEPTION USING errcode='42501',message='Platform administrator permission required';END IF;
 RETURN v_user;
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_admin_guard() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_set_document_requirement(p_registration_country_code text,p_vehicle_category text,p_document_type text,p_is_required boolean DEFAULT true)
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();v_id bigint;
BEGIN
 INSERT INTO public.krim_vehicle_document_requirements(registration_country_code,vehicle_category,document_type,is_required,created_by)
 VALUES(upper(btrim(p_registration_country_code)),btrim(p_vehicle_category),btrim(p_document_type),p_is_required,v_user)
 ON CONFLICT(registration_country_code,lower(vehicle_category),document_type)
 DO UPDATE SET is_required=excluded.is_required,updated_at=now()
 RETURNING id INTO v_id;
 INSERT INTO public.krim_audit_events(actor_user_id,event_type,entity_type,entity_id,source,metadata,new_state)
 VALUES(v_user,'vehicle.document_requirement.updated','vehicle_document_requirement',v_id::text,'vehicle-verification-console',
 jsonb_build_object('country',upper(btrim(p_registration_country_code)),'category',btrim(p_vehicle_category),'document_type',btrim(p_document_type)),
 jsonb_build_object('is_required',p_is_required));
 RETURN v_id;
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_set_document_requirement(text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_set_document_requirement(text,text,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_review_queue()
RETURNS TABLE(document_id uuid,vehicle_id uuid,organization_id bigint,registration_country_code text,registration_number text,vehicle_category text,vehicle_type text,document_type text,document_number text,issuing_country_code text,issued_at date,expires_at date,storage_path text,original_file_name text,content_type text,file_size bigint,review_status text,created_by uuid,created_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();
BEGIN
 RETURN QUERY SELECT d.id,v.id,v.organization_id,v.registration_country_code,v.registration_number,v.vehicle_category,v.vehicle_type,d.document_type,d.document_number,d.issuing_country_code,d.issued_at,d.expires_at,d.storage_path,d.original_file_name,d.content_type,d.file_size,d.review_status,d.created_by,d.created_at
 FROM public.krim_vehicle_documents d JOIN public.krim_vehicles v ON v.id=d.vehicle_id WHERE d.review_status IN('pending','in_review') ORDER BY d.created_at ASC;
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_review_queue() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_review_queue() TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_review_document(p_document_id uuid,p_decision text,p_reason text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();v_doc public.krim_vehicle_documents%ROWTYPE;
BEGIN
 IF p_decision IS NULL OR p_decision NOT IN('approved','rejected') THEN RAISE EXCEPTION USING errcode='22023',message='Decision must be approved or rejected';END IF;
 IF p_decision='rejected' AND length(btrim(coalesce(p_reason,'')))<5 THEN RAISE EXCEPTION USING errcode='22023',message='A clear rejection reason is required';END IF;
 SELECT * INTO v_doc FROM public.krim_vehicle_documents WHERE id=p_document_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0002',message='Vehicle document not found';END IF;
 IF v_doc.created_by=v_user THEN RAISE EXCEPTION USING errcode='42501',message='A reviewer cannot approve or reject their own submission';END IF;
 IF v_doc.review_status IN('approved','rejected','expired') THEN RAISE EXCEPTION USING errcode='55000',message='This document has already received a final decision';END IF;
 IF p_decision='approved' AND v_doc.expires_at IS NOT NULL AND v_doc.expires_at<current_date THEN RAISE EXCEPTION USING errcode='23514',message='Expired evidence cannot be approved';END IF;
 UPDATE public.krim_vehicle_documents SET review_status=p_decision,review_reason=nullif(btrim(p_reason),''),reviewed_by=v_user,reviewed_at=now() WHERE id=p_document_id;
 INSERT INTO public.krim_audit_events(actor_user_id,organization_id,event_type,entity_type,entity_id,source,metadata,previous_state,new_state)
 VALUES(v_user,v_doc.organization_id,'vehicle.document.reviewed','vehicle_document',v_doc.id::text,'vehicle-verification-console',jsonb_build_object('decision',p_decision,'reason',nullif(btrim(p_reason),'')),jsonb_build_object('review_status',v_doc.review_status),jsonb_build_object('review_status',p_decision,'reviewed_at',now()));
 RETURN p_decision;
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_review_document(uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_review_document(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_finalize_verification(p_vehicle_id uuid)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();v_vehicle public.krim_vehicles%ROWTYPE;v_req_count integer;
BEGIN
 SELECT * INTO v_vehicle FROM public.krim_vehicles WHERE id=p_vehicle_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING errcode='P0002',message='Vehicle not found';END IF;
 IF v_vehicle.created_by=v_user THEN RAISE EXCEPTION USING errcode='42501',message='Vehicle registrant cannot independently verify this vehicle';END IF;
 SELECT count(*) INTO v_req_count FROM public.krim_vehicle_document_requirements r WHERE r.registration_country_code=v_vehicle.registration_country_code AND lower(r.vehicle_category)=lower(v_vehicle.vehicle_category) AND r.is_required=true;
 IF v_req_count=0 THEN RAISE EXCEPTION USING errcode='55000',message='No approved country and vehicle-category document requirement profile exists; configure requirements before verification';END IF;
 IF EXISTS(SELECT 1 FROM public.krim_vehicle_document_requirements r WHERE r.registration_country_code=v_vehicle.registration_country_code AND lower(r.vehicle_category)=lower(v_vehicle.vehicle_category) AND r.is_required=true AND NOT EXISTS(SELECT 1 FROM public.krim_vehicle_documents d WHERE d.vehicle_id=v_vehicle.id AND d.document_type=r.document_type AND d.review_status='approved' AND (d.expires_at IS NULL OR d.expires_at>=current_date))) THEN RAISE EXCEPTION USING errcode='55000',message='One or more mandatory documents are missing, unapproved or expired';END IF;
 IF EXISTS(SELECT 1 FROM public.krim_vehicle_documents d WHERE d.vehicle_id=v_vehicle.id AND d.created_by=v_user) THEN RAISE EXCEPTION USING errcode='42501',message='A reviewer cannot verify a vehicle containing evidence they submitted';END IF;
 UPDATE public.krim_vehicles SET verification_status='verified',operational_status='active',verified_at=now(),verified_by=v_user,updated_at=now() WHERE id=p_vehicle_id;
 INSERT INTO public.krim_audit_events(actor_user_id,organization_id,event_type,entity_type,entity_id,source,metadata,previous_state,new_state)
 VALUES(v_user,v_vehicle.organization_id,'vehicle.verified','vehicle',v_vehicle.id::text,'vehicle-verification-console',jsonb_build_object('country',v_vehicle.registration_country_code,'category',v_vehicle.vehicle_category,'requirements_checked',v_req_count),jsonb_build_object('verification_status',v_vehicle.verification_status,'operational_status',v_vehicle.operational_status),jsonb_build_object('verification_status','verified','operational_status','active','verified_at',now()));
 RETURN 'verified';
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_finalize_verification(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_finalize_verification(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_refresh_expiry()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();v_docs integer:=0;v_vehicles integer:=0;
BEGIN
 WITH changed AS (
  UPDATE public.krim_vehicle_documents d SET review_status='expired',review_reason=coalesce(d.review_reason,'Evidence expiry date has passed.'),reviewed_at=now()
  WHERE d.review_status='approved' AND d.expires_at IS NOT NULL AND d.expires_at<current_date
  RETURNING d.id,d.organization_id,d.vehicle_id,d.expires_at
 )
 INSERT INTO public.krim_audit_events(actor_user_id,organization_id,event_type,entity_type,entity_id,source,metadata,new_state)
 SELECT v_user,c.organization_id,'vehicle.document.expired','vehicle_document',c.id::text,'vehicle-expiry-monitor',jsonb_build_object('expires_at',c.expires_at),jsonb_build_object('review_status','expired') FROM changed c;
 GET DIAGNOSTICS v_docs=ROW_COUNT;
 WITH changed AS (
  UPDATE public.krim_vehicles v SET verification_status='expired',operational_status='suspended',updated_at=now()
  WHERE v.verification_status='verified' AND EXISTS(
   SELECT 1 FROM public.krim_vehicle_document_requirements r
   WHERE r.registration_country_code=v.registration_country_code AND lower(r.vehicle_category)=lower(v.vehicle_category) AND r.is_required=true
   AND NOT EXISTS(SELECT 1 FROM public.krim_vehicle_documents d WHERE d.vehicle_id=v.id AND d.document_type=r.document_type AND d.review_status='approved' AND (d.expires_at IS NULL OR d.expires_at>=current_date))
  )
  RETURNING v.id,v.organization_id,v.verification_status,v.operational_status
 )
 INSERT INTO public.krim_audit_events(actor_user_id,organization_id,event_type,entity_type,entity_id,source,metadata,new_state)
 SELECT v_user,c.organization_id,'vehicle.suspended_expired_evidence','vehicle',c.id::text,'vehicle-expiry-monitor',jsonb_build_object('reason','Mandatory evidence expired or is no longer valid'),jsonb_build_object('verification_status',c.verification_status,'operational_status',c.operational_status) FROM changed c;
 GET DIAGNOSTICS v_vehicles=ROW_COUNT;
 RETURN jsonb_build_object('expired_documents',v_docs,'suspended_vehicles',v_vehicles,'checked_at',now());
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_refresh_expiry() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_refresh_expiry() TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_requirement_list()
RETURNS TABLE(registration_country_code text,vehicle_category text,document_type text,is_required boolean)
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();
BEGIN RETURN QUERY SELECT r.registration_country_code,r.vehicle_category,r.document_type,r.is_required FROM public.krim_vehicle_document_requirements r ORDER BY r.registration_country_code,r.vehicle_category,r.document_type; END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_requirement_list() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_requirement_list() TO authenticated;
CREATE OR REPLACE FUNCTION public.krim_vehicle_admin_vehicle_list()
RETURNS TABLE(vehicle_id uuid,organization_id bigint,registration_country_code text,registration_number text,vehicle_category text,vehicle_type text,verification_status text,operational_status text,required_documents bigint,satisfied_documents bigint)
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_user uuid:=public.krim_vehicle_admin_guard();
BEGIN
 RETURN QUERY SELECT v.id,v.organization_id,v.registration_country_code,v.registration_number,v.vehicle_category,v.vehicle_type,v.verification_status,v.operational_status,
 (SELECT count(*) FROM public.krim_vehicle_document_requirements r WHERE r.registration_country_code=v.registration_country_code AND lower(r.vehicle_category)=lower(v.vehicle_category) AND r.is_required=true),
 (SELECT count(*) FROM public.krim_vehicle_document_requirements r WHERE r.registration_country_code=v.registration_country_code AND lower(r.vehicle_category)=lower(v.vehicle_category) AND r.is_required=true AND EXISTS(SELECT 1 FROM public.krim_vehicle_documents d WHERE d.vehicle_id=v.id AND d.document_type=r.document_type AND d.review_status='approved' AND (d.expires_at IS NULL OR d.expires_at>=current_date)))
 FROM public.krim_vehicles v WHERE v.verification_status<>'verified' ORDER BY v.created_at ASC;
END;$$;
REVOKE ALL ON FUNCTION public.krim_vehicle_admin_vehicle_list() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.krim_vehicle_admin_vehicle_list() TO authenticated;